package com.jeshwin.crashlab;
import static org.junit.jupiter.api.Assertions.*;import java.util.UUID;import org.junit.jupiter.api.Test;
class DedupPostgresTest { @Test void commitsOnceAndSkipsDuplicate() throws Exception {String id=UUID.randomUUID().toString(),a="test-"+id;try(var d=DatabaseWork.open();var s=d.prepareStatement("INSERT INTO accounts(account_id,balance) VALUES (?,0)")){s.setString(1,a);s.executeUpdate();}var one=DatabaseWork.begin("dedup-db-first",id,a);assertTrue(one.applied());one.connection().commit();one.connection().close();var two=DatabaseWork.begin("dedup-db-first",id,a);assertFalse(two.applied());two.connection().commit();two.connection().close();} @Test void rejectsChangedAccountAndUnknownLegacyContent() throws Exception {String id=UUID.randomUUID().toString(),a="test-"+id,b="other-"+id,legacy="legacy-"+id;try(var d=DatabaseWork.open();var s=d.prepareStatement("INSERT INTO accounts(account_id,balance) VALUES (?,0),(?,0); INSERT INTO processed_events(handler_scope,event_id) VALUES (?,?)")){s.setString(1,a);s.setString(2,b);s.setString(3,DatabaseWork.DEDUP_SCOPE);s.setString(4,legacy);s.execute();}var one=DatabaseWork.begin("dedup-db-first",id,a);one.connection().commit();one.connection().close();assertThrows(IllegalStateException.class,()->DatabaseWork.begin("dedup-db-first",id,b));assertThrows(IllegalStateException.class,()->DatabaseWork.begin("dedup-db-first",legacy,a));} }
